const QDRANT_URL = 'http://qdrant:6333';
const QDRANT_API_KEY = process.env.QDRANT_API_KEY || '';
const OLLAMA_URL = 'http://host.docker.internal:11434';

async function qdrantScroll(collection, filter, limit=100) {
  const body = {limit, with_payload: true, with_vector: false};
  if (filter) body.filter = filter;
  const r = await fetch(`${QDRANT_URL}/collections/${collection}/points/scroll`, {
    method: 'POST', headers: {'api-key': QDRANT_API_KEY, 'Content-Type': 'application/json'},
    body: JSON.stringify(body)
  });
  const d = await r.json();
  return d.result?.points || [];
}

async function qdrantStore(collection, id, vector, payload) {
  await fetch(`${QDRANT_URL}/collections/${collection}/points`, {
    method: 'PUT', headers: {'api-key': QDRANT_API_KEY, 'Content-Type': 'application/json'},
    body: JSON.stringify({points: [{id, vector, payload}]})
  });
}

async function qdrantUpdate(collection, ids, payload) {
  await fetch(`${QDRANT_URL}/collections/${collection}/points/payload`, {
    method: 'POST', headers: {'api-key': QDRANT_API_KEY, 'Content-Type': 'application/json'},
    body: JSON.stringify({payload, points: ids})
  });
}

async function embed(text) {
  const r = await fetch(`${OLLAMA_URL}/api/embed`, {
    method: 'POST', headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({model: 'nomic-embed-text', input: text})
  });
  const d = await r.json();
  return d.embeddings?.[0] || null;
}

function uuid() { return crypto.randomUUID(); }

const benchmarks = await qdrantScroll('benchmark_runs', null, 20);
if (benchmarks.length < 2) return [{json: {status: 'insufficient_data', runs: benchmarks.length}}];

// Sort by timestamp desc
benchmarks.sort((a,b) => (b.payload?.timestamp || '').localeCompare(a.payload?.timestamp || ''));

const latest = benchmarks[0]?.payload || {};
const previous = benchmarks[1]?.payload || {};
const regressions = [];

const metrics = ['completion_rate', 'avg_steps', 'avg_cost', 'error_rate', 'governance_compliance'];
for (const metric of metrics) {
  const curr = latest[metric];
  const prev = previous[metric];
  if (curr == null || prev == null || prev === 0) continue;

  const change = ((curr - prev) / prev) * 100;
  // For error_rate and avg_cost, increase is bad. For others, decrease is bad.
  const isRegression = ['error_rate', 'avg_cost', 'avg_steps'].includes(metric) ? change > 10 : change < -10;

  if (isRegression) {
    regressions.push({metric, current: curr, previous: prev, change_pct: Math.round(change * 10) / 10});
  }
}

if (regressions.length > 0) {
  const vec = await embed('benchmark regression detected: ' + regressions.map(r=>r.metric).join(', '));
  if (vec) {
    await qdrantStore('audit_log', uuid(), vec, {
      action: 'BENCHMARK_REGRESSION', timestamp: new Date().toISOString(),
      details: {regressions, latest_run: latest.timestamp, previous_run: previous.timestamp},
      sensitivity: 'internal', project: 'global'
    });
  }
}

return [{json: {regressions: regressions.length, details: regressions}}];
